css='''*{box-sizing:border-box}body{margin:0;background:#24251f;color:#f7efdd;font-family:"Microsoft YaHei",sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer;font:inherit;color:inherit;border:1px solid #c7b18b66;border-radius:12px;background:#242720c9;padding:10px 17px;min-height:44px}button:hover{background:#665742}button:focus-visible,a:focus-visible{outline:3px solid #e0bf80}button:disabled{opacity:.5;cursor:wait}[hidden]{display:none!important}#experience,#view,.shade,#hotspots{position:fixed;inset:0}#view{background:#38382e url('素材/监狱第一幕全景.png') center/cover}#view canvas{width:100%;height:100%;touch-action:none;display:block}.shade{pointer-events:none;background:linear-gradient(#0d110dbb,transparent 24%,transparent 65%,#10150fbb)}#hotspots{pointer-events:none}.hotspot{position:absolute;transform:translate(-50%,-50%);pointer-events:auto;white-space:nowrap;box-shadow:0 0 25px #d8b77855;background:#26332cd9}.hotspot i{display:inline-block;width:10px;height:10px;border-radius:50%;background:#f0cf8e;margin-right:9px;box-shadow:0 0 0 6px #d8b77833;animation:breathe 2s infinite}@keyframes breathe{50%{box-shadow:0 0 0 12px #d8b77805}}header{position:absolute;top:22px;left:30px;right:30px;display:flex;align-items:center;gap:22px}header a{color:#f1dfbb;text-decoration:none;letter-spacing:4px;font-family:serif;font-size:22px}header span{font-size:13px;color:#d6c9b2}header button{margin-left:auto}.heading{position:absolute;left:36px;top:100px;pointer-events:none;text-shadow:0 2px 15px #000}.heading small{color:#d7bd8d;letter-spacing:3px}.heading h1{font-family:serif;font-size:38px;font-weight:400;margin:12px 0}.heading p{font-size:13px;color:#e3d7c0}.tools{position:absolute;right:24px;top:120px;display:grid;gap:9px}.tools button{width:44px;padding:6px}#dialogue{position:absolute;bottom:64px;left:50%;transform:translateX(-50%);width:min(680px,calc(100% - 36px));padding:22px 28px 15px;background:linear-gradient(135deg,#fbf5e9f5,#e9dcc6f5);border:1px solid #c7ad7d;border-radius:20px;color:#302e27;box-shadow:0 15px 60px #0005}.dialogue-top{display:flex;justify-content:space-between;align-items:center}.dialogue-top b{color:#982b28;font-size:18px}.dialogue-top span{font-size:12px;color:#80725d}#line{font-size:20px;line-height:1.8;min-height:58px;margin:12px 0}footer{display:flex;justify-content:space-between;gap:12px}#dialogue button{color:#5a4631;background:transparent}button.primary,#dialogue .primary{background:#982b28;color:#fff5e7;border-color:#982b28}#dialogue small{display:block;color:#8c7e68;font-size:10px;margin-top:12px}#ending{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(530px,calc(100% - 32px));background:#f9f1e3f5;color:#3f392d;border-radius:20px;padding:30px;line-height:1.8}#ending h2{font-family:serif;font-weight:400;color:#982b28}.note{font-size:12px;line-height:1.9;opacity:.75}.bottom{position:absolute;bottom:12px;left:28px;right:28px;display:flex;align-items:center;gap:18px;font-size:11px;color:#d5c6aa}.bottom button{margin-left:auto;font-size:11px;padding:5px 10px;min-height:34px}#welcome{position:absolute;inset:0;background:#101710b0;display:grid;place-items:center;backdrop-filter:blur(5px)}#welcome.hidden{display:none}article{width:min(500px,calc(100% - 32px));padding:34px;background:#f8f0e3;color:#3b352b;border-radius:24px;line-height:1.8}article h2{font-family:serif;font-size:36px;font-weight:400;color:#982b28}article>small{display:block;color:#917957;margin-top:10px}dialog{width:min(560px,calc(100% - 28px));background:#fbf5e9;color:#3c352b;border:1px solid #b99b6e;border-radius:18px;padding:28px;line-height:1.9}dialog::backdrop{background:#0009}@media(max-width:600px){header{top:14px;left:16px;right:16px;gap:10px}header a{font-size:18px}header span{font-size:10px}.heading{left:20px;top:85px;max-width:75%}.heading h1{font-size:28px}.heading p{line-height:1.7}.tools{right:12px;top:110px}.bottom{left:14px;right:14px;gap:8px}.bottom #angle{display:none}#dialogue{padding:18px;bottom:58px}#line{font-size:17px;min-height:64px}article{padding:25px}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}'''
